=== worker/coldemail.ts ===
// Cold Email Engine — send-queue processor (Phase 2).
//
// Registered on the worker loop (worker/index.ts) and gated HARD behind the
// `cold_email_sending_enabled` master kill-switch: while that Setting is false
// this sweep returns immediately and NOTHING is scheduled, rendered, or sent.
//
// For each SENDING campaign it:
//   1. Re-checks brand send-eligibility (compliance + reputation isolation +
//      circuit-breaker pause). A blocked brand is skipped, never sent.
//   2. Expands the list → contacts → schedules a ColdSend per SequenceStep,
//      honouring delayDays (idempotent via the unique (campaign, contact, step)).
//   3. Sends due rows, enforcing at SEND TIME: suppression re-check, per-inbox
//      daily cap with the warmup ramp, and the send window — writing ColdSend
//      status (SENT/FAILED/SUPPRESSED) + an EmailEvent, throttled with jitter.
//
// Every count comes from the DB; the only external call is the SMTP send itself,
// which is unreachable in tests because the kill-switch keeps this inert.

import { db } from "../lib/db";
import { getSetting, getSettingBool } from "../lib/settings";
import {
  isSuppressed,
  evaluateSendEligibility,
  protectedDomainSet,
  effectiveDailyCap,
  openTrackingToken,
  type SuppressionLike,
} from "../lib/coldemail/compliance";
import { buildMessage, getTransport, type SendIdentity, type MailTransport } from "../lib/coldemail/sender";
import { inboxAllowedVolume } from "../lib/coldemail/warmup";
import { selectNextInbox, type RotationInbox } from "../lib/coldemail/rotation";
import { isMailableStatus } from "../lib/coldemail/leaddb";
import { logEvent } from "../lib/log";

/**
 * A brand's rotation pool for this sweep: the ACTIVE inboxes on its authenticated
 * domains, each with the send identity + today's warmup-clamped allowance and the
 * live rotation candidate the selector mutates as sends go out.
 */
type PoolInbox = {
  candidate: RotationInbox;
  identity: SendIdentity;
  sendingDomainId: string;
};

/**
 * Load a brand's rotation pool. Returns [] when the brand has no inboxes — the
 * worker then falls back to the Phase 2 brand-level cap path unchanged. Only
 * inboxes on a domain with SPF+DKIM+DMARC all verified are authenticated (authGreen).
 */
async function loadBrandRotationPool(brandId: string, brand: SendIdentity, now: Date): Promise<PoolInbox[]> {
  let inboxes;
  try {
    inboxes = await db.inbox.findMany({
      // Only ACTIVE inboxes on a domain that is not paused/burned. A domain-level
      // auto-pause therefore takes every one of its inboxes out of rotation.
      where: { status: "ACTIVE", sendingDomain: { brandId, status: { notIn: ["PAUSED", "BURNED"] } } },
      include: { sendingDomain: true },
    });
  } catch {
    return []; // tables not migrated on this env — behave like Phase 2
  }
  if (inboxes.length === 0) return [];

  const dayStart = startOfUtcDay(now);
  const pool: PoolInbox[] = [];
  for (const ib of inboxes) {
    const d = ib.sendingDomain;
    const authGreen = !!(d?.spfVerified && d?.dkimVerified && d?.dmarcVerified);
    const allowedToday = inboxAllowedVolume({
      warmupStartedAt: ib.warmupStartedAt,
      plan: { startCap: ib.startCap, targetCap: ib.targetCap, rampDays: ib.rampDays },
      dailyCap: ib.dailyCap,
      healthScore: ib.healthScore,
      adaptive: ib.strategy === "ADAPTIVE",
      now,
    });
    const sentToday = await db.coldSend.count({ where: { inboxId: ib.id, sentAt: { gte: dayStart } } });
    pool.push({
      sendingDomainId: ib.sendingDomainId,
      candidate: {
        id: ib.id,
        status: ib.status as RotationInbox["status"],
        allowedToday,
        sentToday,
        authGreen,
        lastSendAt: ib.lastSendAt,
        minGapSeconds: ib.minGapSeconds,
      },
      // Send AS the inbox address, keeping the brand's name/postal/reply-to. This is
      // what makes rotation real — each message goes out from a different mailbox.
      identity: {
        ...brand,
        fromEmail: ib.email,
        sendingDomain: d ? `${d.subdomain ? d.subdomain + "." : ""}${d.domain}` : brand.sendingDomain,
      },
    });
  }
  return pool;
}

/** Append a deliverability event (the analytics spine). Never throws to the caller. */
async function recordDeliverability(
  type: "SENT" | "FAILED" | "DELIVERED",
  ctx: { inboxId?: string | null; sendingDomainId?: string | null; campaignId: string; contactId?: string | null; sendId: string; meta?: string },
): Promise<void> {
  const t = type === "FAILED" ? "DEFERRED" : type; // FAILED maps to a soft/deferred signal
  try {
    await db.deliverabilityEvent.create({
      data: {
        type: t,
        inboxId: ctx.inboxId ?? null,
        sendingDomainId: ctx.sendingDomainId ?? null,
        campaignId: ctx.campaignId,
        contactId: ctx.contactId ?? null,
        sendId: ctx.sendId,
        meta: (ctx.meta ?? "").slice(0, 300),
      },
    });
  } catch {
    /* table not migrated / best-effort — analytics must never fail a send */
  }
}

/** Upper bound on sends per sweep — keeps each worker tick light + jitter sane. */
const MAX_SENDS_PER_SWEEP = 50;
/** Throttle window (ms) between real sends — jittered to look human, not blasty. */
const THROTTLE_MIN_MS = 800;
const THROTTLE_MAX_MS = 2600;

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const jitter = () => THROTTLE_MIN_MS + Math.floor(Math.random() * (THROTTLE_MAX_MS - THROTTLE_MIN_MS));

function appHost(): string | null {
  try {
    return process.env.APP_URL ? new URL(process.env.APP_URL).host : null;
  } catch {
    return null;
  }
}

function startOfUtcDay(now = new Date()): Date {
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
}

/** Current minute-of-day in a timezone (falls back to UTC on a bad tz). */
function minutesInTz(now: Date, tz: string): number {
  try {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone: tz || "UTC",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    }).formatToParts(now);
    const h = Number(parts.find((p) => p.type === "hour")?.value ?? "0") % 24;
    const m = Number(parts.find((p) => p.type === "minute")?.value ?? "0");
    return h * 60 + m;
  } catch {
    return now.getUTCHours() * 60 + now.getUTCMinutes();
  }
}

function withinSendWindow(
  c: { sendWindowStart: number | null; sendWindowEnd: number | null; timezone: string },
  now: Date,
): boolean {
  if (c.sendWindowStart == null || c.sendWindowEnd == null) return true;
  const cur = minutesInTz(now, c.timezone || "UTC");
  const s = c.sendWindowStart;
  const e = c.sendWindowEnd;
  return s <= e ? cur >= s && cur < e : cur >= s || cur < e; // handle wrap past midnight
}

type CampaignForSend = {
  id: string;
  brandId: string;
  listId: string;
  launchedAt: Date | null;
  sendWindowStart: number | null;
  sendWindowEnd: number | null;
  timezone: string;
};

/**
 * Ensure a ColdSend row exists for every (contact, step) in a campaign, with the
 * scheduledFor honouring cumulative step delays from the launch anchor. Idempotent
 * — the unique(campaignId, contactId, stepId) + skipDuplicates makes re-runs free.
 */
async function scheduleCampaignSends(campaign: CampaignForSend): Promise<void> {
  const steps = await db.sequenceStep.findMany({
    where: { campaignId: campaign.id },
    orderBy: { stepOrder: "asc" },
    select: { id: true, delayDays: true },
  });
  if (steps.length === 0) return;

  const base = campaign.launchedAt ?? new Date();
  // Cumulative offset (days) at each step.
  let cumulative = 0;
  const stepSchedule = steps.map((s) => {
    cumulative += Math.max(0, s.delayDays);
    return { stepId: s.id, scheduledFor: new Date(base.getTime() + cumulative * 86_400_000) };
  });

  const members = await db.emailListMember.findMany({
    where: { listId: campaign.listId },
    select: { contactId: true, contact: { select: { email: true, emailStatus: true } } },
  });
  if (members.length === 0) return;

  // LEAD-DB exclusion: never schedule a send for a non-mailable (dead / hard-bounced
  // / complained / unsubscribed) or globally/brand-suppressed contact. The send-time
  // suppression re-check remains as defence-in-depth for rows queued earlier.
  const suppressions: SuppressionLike[] = await db.suppression.findMany({
    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
    select: { email: true, domain: true, scope: true, brandId: true },
  });

  const rows: { campaignId: string; contactId: string; stepId: string; scheduledFor: Date }[] = [];
  for (const m of members) {
    if (!isMailableStatus(m.contact?.emailStatus)) continue;
    if (m.contact?.email && isSuppressed(m.contact.email, campaign.brandId, suppressions)) continue;
    for (const s of stepSchedule) {
      rows.push({ campaignId: campaign.id, contactId: m.contactId, stepId: s.stepId, scheduledFor: s.scheduledFor });
    }
  }
  if (rows.length === 0) return;
  // createMany + skipDuplicates: never double-queues a message across sweeps.
  await db.coldSend.createMany({ data: rows, skipDuplicates: true });
}

/**
 * Process due sends for one eligible campaign. Returns the number actually sent so
 * the caller can respect the per-sweep budget across campaigns.
 */
async function processDueSends(
  campaign: CampaignForSend,
  identity: SendIdentity,
  ctx: {
    now: Date;
    transport: MailTransport;
    ceiling: number;
    warmupEnabled: boolean;
    footerDisclosure: string;
    budget: number;
  },
): Promise<number> {
  if (ctx.budget <= 0) return 0;
  if (!withinSendWindow(campaign, ctx.now)) return 0;

  // ===== Phase 3 — rotation pool =====
  // If the brand has ACTIVE inboxes, distribute sends across them honouring each
  // inbox's warmup limit + dailyCap + min gap (rotation.selectNextInbox). Otherwise
  // fall back to the Phase 2 brand-level warmup cap (unchanged).
  const pool = await loadBrandRotationPool(campaign.brandId, identity, ctx.now);
  const useRotation = pool.length > 0;
  const poolById = new Map(pool.map((p) => [p.candidate.id, p]));

  // Per-inbox daily cap (warmup-aware). Counts REAL sends today for the brand.
  const brand = await db.brand.findUnique({
    where: { id: campaign.brandId },
    select: { warmupStartedAt: true, dailySendCap: true },
  });
  const cap = effectiveDailyCap({
    warmupStartedAt: brand?.warmupStartedAt ?? null,
    ceiling: brand?.dailySendCap ?? ctx.ceiling,
    warmupEnabled: ctx.warmupEnabled,
    now: ctx.now,
  });
  let sentToday = await db.coldSend.count({
    where: { campaign: { brandId: campaign.brandId }, sentAt: { gte: startOfUtcDay(ctx.now) } },
  });
  if (!useRotation && sentToday >= cap) return 0;

  // Suppression rows for this brand, loaded once (GLOBAL + this brand's BRAND tier).
  const suppressions: SuppressionLike[] = await db.suppression.findMany({
    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
    select: { email: true, domain: true, scope: true, brandId: true },
  });

  const due = await db.coldSend.findMany({
    where: {
      campaignId: campaign.id,
      status: "QUEUED",
      stepId: { not: null },
      scheduledFor: { lte: ctx.now },
    },
    orderBy: { scheduledFor: "asc" },
    take: ctx.budget,
    include: {
      contact: {
        select: { id: true, email: true, fullName: true, title: true, firstEmailedAt: true, business: { select: { name: true } } },
      },
      step: { select: { subject: true, bodyMarkdown: true } },
    },
  });

  let sent = 0;
  for (const s of due) {
    if (!s.step || !s.contact) continue;

    // GUARDRAIL #4 — re-check suppression immediately before the send.
    if (isSuppressed(s.contact.email, campaign.brandId, suppressions)) {
      await db.coldSend.update({ where: { id: s.id }, data: { status: "SUPPRESSED" } });
      continue;
    }

    // Pick the sending inbox (rotation) or fall back to the brand identity + cap.
    let chosen: PoolInbox | null = null;
    if (useRotation) {
      const cand = selectNextInbox(pool.map((p) => p.candidate), ctx.now);
      if (!cand) break; // no eligible inbox right now — leave the rest QUEUED
      chosen = poolById.get(cand.id) ?? null;
      if (!chosen) break;
    } else if (sentToday >= cap) {
      break; // brand-level cap reached
    }

    const sendIdentity = chosen ? chosen.identity : identity;
    const token = openTrackingToken(s.id);
    const msg = buildMessage({
      identity: sendIdentity,
      step: s.step,
      contact: s.contact,
      sendId: s.id,
      footerDisclosure: ctx.footerDisclosure,
      track: true,
    });

    try {
      const res = await ctx.transport.send(msg);
      const sentAt = new Date();
      await db.coldSend.update({
        where: { id: s.id },
        data: {
          status: "SENT",
          sentAt,
          inboxId: chosen?.candidate.id ?? null,
          messageId: res.messageId ?? null,
          trackingToken: token,
          error: null,
        },
      });
      await db.emailEvent.create({ data: { sendId: s.id, type: "SENT" } });
      // LEAD-DB engagement counters: this contact was just emailed.
      await db.contact
        .update({
          where: { id: s.contact.id },
          data: {
            timesEmailed: { increment: 1 },
            lastEmailedAt: sentAt,
            lastCampaignId: campaign.id,
            ...(s.contact.firstEmailedAt ? {} : { firstEmailedAt: sentAt }),
          },
        })
        .catch(() => null);
      await recordDeliverability("SENT", {
        inboxId: chosen?.candidate.id ?? null,
        sendingDomainId: chosen?.sendingDomainId ?? null,
        campaignId: campaign.id,
        contactId: s.contact.id,
        sendId: s.id,
      });
      if (chosen) {
        // Advance the rotation state so successive picks rotate + honour the gap.
        chosen.candidate.sentToday += 1;
        chosen.candidate.lastSendAt = sentAt;
        await db.inbox.update({ where: { id: chosen.candidate.id }, data: { lastSendAt: sentAt } }).catch(() => null);
      }
      sentToday++;
      sent++;
    } catch (err) {
      const error = String((err as Error)?.message ?? err).slice(0, 500);
      await db.coldSend.update({ where: { id: s.id }, data: { status: "FAILED", error, inboxId: chosen?.candidate.id ?? null, trackingToken: token } });
      await db.emailEvent.create({ data: { sendId: s.id, type: "FAILED", meta: error } });
      await recordDeliverability("FAILED", {
        inboxId: chosen?.candidate.id ?? null,
        sendingDomainId: chosen?.sendingDomainId ?? null,
        campaignId: campaign.id,
        contactId: s.contact.id,
        sendId: s.id,
        meta: error,
      });
      await logEvent("error", "coldemail.send.fail", { campaignId: campaign.id, sendId: s.id, error });
    }

    await sleep(jitter());
  }
  return sent;
}

/** Mark a campaign DONE once nothing is left QUEUED (all sends terminal). */
async function maybeCompleteCampaign(campaignId: string): Promise<void> {
  const remaining = await db.coldSend.count({ where: { campaignId, status: "QUEUED" } });
  if (remaining > 0) return;
  const any = await db.coldSend.count({ where: { campaignId } });
  if (any === 0) return; // nothing was ever scheduled — leave it SENDING
  await db.coldCampaign.update({ where: { id: campaignId }, data: { status: "DONE" } });
}

/**
 * The send sweep. GATED by `cold_email_sending_enabled` — the single line that
 * keeps everything below inert until a human enables sending on prod.
 */
export async function coldEmailSendSweep(): Promise<void> {
  // ===== GUARDRAIL #1 — MASTER KILL-SWITCH =====
  if (!(await getSettingBool("cold_email_sending_enabled", false))) return;

  let campaigns: CampaignForSend[];
  try {
    campaigns = await db.coldCampaign.findMany({
      where: { status: "SENDING" },
      select: {
        id: true,
        brandId: true,
        listId: true,
        launchedAt: true,
        sendWindowStart: true,
        sendWindowEnd: true,
        timezone: true,
      },
    });
  } catch {
    // Table not migrated on this environment yet — no-op (mirrors marketing sweep).
    return;
  }
  if (campaigns.length === 0) return;

  const protectedSet = protectedDomainSet(await getSetting("cold_email_protected_domains"), appHost());
  const ceiling = getSettingIntSafe(await getSetting("coldemail_warmup_ceiling"), 40);
  const warmupEnabled = (await getSetting("coldemail_warmup_enabled")) !== "false";
  const footerDisclosure = await getSetting("coldemail_footer_disclosure");
  const now = new Date();

  let transport: MailTransport;
  try {
    transport = await getTransport("nxeon-smtp");
  } catch (err) {
    await logEvent("error", "coldemail.transport.init", { message: String(err) });
    return;
  }

  let budget = MAX_SENDS_PER_SWEEP;
  for (const campaign of campaigns) {
    if (budget <= 0) break;

    const brand = await db.brand.findUnique({ where: { id: campaign.brandId } });
    if (!brand) continue;

    // ===== GUARDRAILS #2 + #3 — reputation isolation + per-brand gate =====
    const eligibility = evaluateSendEligibility(brand, protectedSet);
    if (!eligibility.eligible) {
      await logEvent("warn", "coldemail.send.brand_blocked", {
        campaignId: campaign.id,
        brandId: brand.id,
        reasons: eligibility.reasons,
      });
      continue;
    }

    const identity: SendIdentity = {
      id: brand.id,
      name: brand.name,
      fromName: brand.fromName,
      fromEmail: brand.fromEmail,
      replyTo: brand.replyTo,
      sendingDomain: brand.sendingDomain,
      physicalPostalAddress: brand.physicalPostalAddress,
    };

    try {
      await scheduleCampaignSends(campaign);
      const sent = await processDueSends(campaign, identity, {
        now,
        transport,
        ceiling,
        warmupEnabled,
        footerDisclosure,
        budget,
      });
      budget -= sent;
      await maybeCompleteCampaign(campaign.id);
    } catch (err) {
      await logEvent("error", "coldemail.send.campaign", { campaignId: campaign.id, message: String(err) });
    }
  }
}

function getSettingIntSafe(raw: string, fallback: number): number {
  const n = Number(raw);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallback;
}

=== worker/coldemail-deliverability.ts ===
// Cold Email Engine — warmup + deliverability rollup / auto-pause sweeps (Phase 3).
//
// Two background passes, both safe to run regardless of the send kill-switch
// because NEITHER sends mail — they maintain warmup state and roll DeliverabilityEvent
// rows into MetricsDaily / HealthSnapshot, then AUTO-PAUSE inboxes/domains whose
// bounce or complaint rate crossed a burn threshold (research §4). All queries are
// tolerant of un-migrated tables (mirrors the send sweep).

import { db } from "../lib/db";
import { getSetting } from "../lib/settings";
import { logEvent } from "../lib/log";
import { inboxAllowedVolume, warmupStatus } from "../lib/coldemail/warmup";
import { warmupDayIndex } from "../lib/coldemail/compliance";
import {
  resolveThresholds,
  evaluateInboxAutoPause,
  evaluateDomainAutoPause,
  bounceRate,
  complaintRate,
  type BurnThresholds,
  type RateStats,
} from "../lib/coldemail/rotation";
import { addCounts, deriveRates, healthScore, healthLevel, ZERO_COUNTS, type MetricCounts } from "../lib/coldemail/analytics";
import { reconcileEmailStatus } from "../lib/coldemail/leaddb";
import type { EmailEventType } from "@prisma/client";

function startOfUtcDay(now = new Date()): Date {
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
}

// ---------------------------------------------------------------------------
// Warmup sweep — recompute each inbox's ramp cap + today's WarmupState, and
// promote a fully-warmed, authenticated inbox from WARMING → ACTIVE.
// ---------------------------------------------------------------------------

export async function coldEmailWarmupSweep(): Promise<void> {
  let inboxes;
  try {
    inboxes = await db.inbox.findMany({
      where: { status: { in: ["WARMING", "ACTIVE"] } },
      include: { sendingDomain: { select: { spfVerified: true, dkimVerified: true, dmarcVerified: true } } },
    });
  } catch {
    return; // tables not migrated on this env
  }

  const now = new Date();
  const day0 = startOfUtcDay(now);

  for (const ib of inboxes) {
    const plan = { startCap: ib.startCap, targetCap: ib.targetCap, rampDays: ib.rampDays };
    const day = warmupDayIndex(ib.warmupStartedAt, now);
    const status = warmupStatus(day, plan);
    const currentRampCap = inboxAllowedVolume({
      warmupStartedAt: ib.warmupStartedAt,
      plan,
      dailyCap: ib.dailyCap,
      healthScore: ib.healthScore,
      adaptive: ib.strategy === "ADAPTIVE",
      now,
    });

    try {
      await db.inbox.update({ where: { id: ib.id }, data: { warmupDay: day, currentRampCap } });

      // Actual sends made by this inbox today (for the planned-vs-actual curve).
      const sentVolume = await db.coldSend.count({ where: { inboxId: ib.id, sentAt: { gte: day0 } } });
      await db.warmupState.upsert({
        where: { inboxId_date: { inboxId: ib.id, date: day0 } },
        create: {
          inboxId: ib.id,
          date: day0,
          day,
          plannedVolume: currentRampCap,
          sentVolume,
          healthScore: ib.healthScore,
        },
        update: { day, plannedVolume: currentRampCap, sentVolume, healthScore: ib.healthScore },
      });

      // Promote a warmed + authenticated inbox to ACTIVE (rotation-eligible). We only
      // auto-promote; we never auto-pause here (that's the rollup sweep's job).
      const d = ib.sendingDomain;
      const authGreen = !!(d?.spfVerified && d?.dkimVerified && d?.dmarcVerified);
      if (ib.status === "WARMING" && status.complete && authGreen) {
        await db.inbox.update({ where: { id: ib.id }, data: { status: "ACTIVE", pausedReason: "" } });
        await logEvent("info", "coldemail.warmup.complete", { inboxId: ib.id, day });
      }
    } catch (err) {
      await logEvent("error", "coldemail.warmup.sweep", { inboxId: ib.id, message: String(err) });
    }
  }
}

// ---------------------------------------------------------------------------
// Rollup + auto-pause sweep
// ---------------------------------------------------------------------------

const EVENT_TO_COUNT: Record<string, Partial<MetricCounts>> = {
  SENT: { sent: 1 },
  DELIVERED: { delivered: 1 },
  HARD_BOUNCE: { hardBounce: 1 },
  SOFT_BOUNCE: { softBounce: 1 },
  OPEN: { opens: 1 },
  CLICK: { uniqueClicks: 1 },
  REPLY: { replies: 1 },
  POSITIVE_REPLY: { positiveReplies: 1, replies: 1 },
  COMPLAINT: { complaints: 1 },
  UNSUBSCRIBE: { unsubscribes: 1 },
};

type Grouped = Map<string, MetricCounts>;

function bump(map: Grouped, key: string | null | undefined, delta: Partial<MetricCounts>): void {
  if (!key) return;
  map.set(key, addCounts(map.get(key) ?? ZERO_COUNTS, delta));
}

async function upsertMetrics(scope: "INBOX" | "DOMAIN" | "CAMPAIGN" | "BRAND", date: Date, map: Grouped): Promise<void> {
  for (const [scopeId, c] of map) {
    await db.metricsDaily
      .upsert({
        where: { scope_scopeId_date: { scope, scopeId, date } },
        create: { scope, scopeId, date, ...c },
        update: { ...c },
      })
      .catch(() => null);
  }
}

/** Aggregate this UTC day's DeliverabilityEvent rows into MetricsDaily by scope. */
export async function coldEmailRollupSweep(): Promise<void> {
  const now = new Date();
  const day0 = startOfUtcDay(now);

  let events;
  try {
    events = await db.deliverabilityEvent.findMany({
      where: { occurredAt: { gte: day0 } },
      select: { type: true, inboxId: true, sendingDomainId: true, campaignId: true },
    });
  } catch {
    return; // not migrated
  }

  const byInbox: Grouped = new Map();
  const byDomain: Grouped = new Map();
  const byCampaign: Grouped = new Map();
  const brandByDomain = new Map<string, string>();

  for (const e of events) {
    const delta = EVENT_TO_COUNT[e.type];
    if (!delta) continue;
    bump(byInbox, e.inboxId, delta);
    bump(byDomain, e.sendingDomainId, delta);
    bump(byCampaign, e.campaignId, delta);
  }

  try {
    await upsertMetrics("INBOX", day0, byInbox);
    await upsertMetrics("DOMAIN", day0, byDomain);
    await upsertMetrics("CAMPAIGN", day0, byCampaign);
  } catch (err) {
    await logEvent("error", "coldemail.rollup.upsert", { message: String(err) });
  }

  // Roll domains up to their brand for the agency/multi-client view.
  const byBrand: Grouped = new Map();
  for (const [domainId, c] of byDomain) {
    let brandId = brandByDomain.get(domainId);
    if (!brandId) {
      const d = await db.sendingDomain.findUnique({ where: { id: domainId }, select: { brandId: true } }).catch(() => null);
      brandId = d?.brandId;
      if (brandId) brandByDomain.set(domainId, brandId);
    }
    if (brandId) bump(byBrand, brandId, c);
  }
  await upsertMetrics("BRAND", day0, byBrand).catch(() => null);

  // Auto-pause pass over the trailing window.
  const thresholds = await loadThresholds();
  await evaluateInboxes(thresholds);
  await evaluateDomains(thresholds);

  // LEAD-DB: reconcile contact email-health from bounce/complaint events.
  await coldEmailHygieneSweep().catch(() => null);
}

// ---------------------------------------------------------------------------
// LEAD-DB hygiene reconciliation sweep
// ---------------------------------------------------------------------------

const ADVERSE_EVENT_TYPES = ["HARD_BOUNCE", "SOFT_BOUNCE", "BOUNCE", "COMPLAINT", "UNSUBSCRIBE"] as const;

/**
 * Idempotently recompute each contact's emailStatus from the FULL aggregate of its
 * lifetime adverse EmailEvents, so a bounce/complaint that arrived by any path
 * (feedback route, SNS, manual entry) is reflected on the contact — and a
 * permanent bounce sets HARD_BOUNCED + a GLOBAL suppression. Scoped to contacts
 * with a recent adverse event so the sweep stays cheap. Never throws.
 */
export async function coldEmailHygieneSweep(sinceDays = 3): Promise<void> {
  const threshold = await softBounceDeadThreshold();
  const since = new Date(Date.now() - sinceDays * 86_400_000);

  let recent;
  try {
    recent = await db.emailEvent.findMany({
      where: { type: { in: ADVERSE_EVENT_TYPES as unknown as EmailEventType[] }, createdAt: { gte: since } },
      select: { send: { select: { contactId: true } } },
    });
  } catch {
    return; // not migrated
  }

  const contactIds = Array.from(new Set(recent.map((e) => e.send?.contactId).filter((x): x is string => !!x)));
  for (const contactId of contactIds) {
    try {
      await reconcileOneContact(contactId, threshold);
    } catch (err) {
      await logEvent("error", "coldemail.hygiene.reconcile", { contactId, message: String(err) });
    }
  }
}

async function reconcileOneContact(contactId: string, threshold: number): Promise<void> {
  const contact = await db.contact.findUnique({
    where: { id: contactId },
    select: { id: true, email: true, emailStatus: true, bounceCount: true },
  });
  if (!contact) return;

  // Aggregate this contact's lifetime adverse events (legacy BOUNCE counts as hard).
  const rows = await db.emailEvent.groupBy({
    by: ["type"],
    where: { type: { in: ADVERSE_EVENT_TYPES as unknown as EmailEventType[] }, send: { contactId } },
    _count: { _all: true },
  });
  const counts = { hardBounce: 0, softBounce: 0, complaint: 0, unsubscribe: 0 };
  for (const r of rows as { type: string; _count: { _all: number } }[]) {
    const n = r._count._all;
    if (r.type === "HARD_BOUNCE" || r.type === "BOUNCE") counts.hardBounce += n;
    else if (r.type === "SOFT_BOUNCE") counts.softBounce += n;
    else if (r.type === "COMPLAINT") counts.complaint += n;
    else if (r.type === "UNSUBSCRIBE") counts.unsubscribe += n;
  }

  const res = reconcileEmailStatus(counts, contact, threshold);
  if (!res.changed && !res.suppress) return;

  if (res.changed) {
    await db.contact.update({
      where: { id: contact.id },
      data: {
        emailStatus: res.emailStatus as never,
        bounceCount: res.bounceCount,
        ...(res.dead ? { deadAt: new Date(), ...(res.deadReason ? { deadReason: res.deadReason } : {}) } : {}),
      },
    });
  }

  // Ensure a GLOBAL suppression exists for a now-terminal address (idempotent).
  if (res.suppress && contact.email && res.suppressReason) {
    const existing = await db.suppression.findFirst({ where: { email: contact.email, scope: "GLOBAL" }, select: { id: true } });
    if (!existing) {
      await db.suppression.create({ data: { email: contact.email, scope: "GLOBAL", reason: res.suppressReason } }).catch(() => null);
    }
  }
}

async function softBounceDeadThreshold(): Promise<number> {
  const n = Number(await getSetting("coldemail_soft_bounce_dead_threshold"));
  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : 3;
}

async function loadThresholds(): Promise<BurnThresholds> {
  const num = async (key: string) => {
    const v = Number(await getSetting(key));
    return Number.isFinite(v) && v > 0 ? v : undefined;
  };
  return resolveThresholds({
    bouncePauseInbox: await num("coldemail_bounce_pause_inbox"),
    bouncePauseDomain: await num("coldemail_bounce_pause_domain"),
    bounceHardStop: await num("coldemail_bounce_hard_stop"),
    complaintPauseDomain: await num("coldemail_complaint_pause_domain"),
  });
}

/** RateStats for a scope over a trailing window (default 7 days). */
async function statsForScope(where: Record<string, unknown>, sinceDays = 7): Promise<RateStats> {
  const since = new Date(Date.now() - sinceDays * 86_400_000);
  const rows = await db.deliverabilityEvent
    .groupBy({ by: ["type"], where: { ...where, occurredAt: { gte: since } }, _count: { _all: true } })
    .catch(() => [] as { type: string; _count: { _all: number } }[]);
  let sent = 0,
    delivered = 0,
    bounces = 0,
    complaints = 0;
  for (const r of rows as { type: string; _count: { _all: number } }[]) {
    const n = r._count._all;
    if (r.type === "SENT") sent += n;
    else if (r.type === "DELIVERED") delivered += n;
    else if (r.type === "HARD_BOUNCE" || r.type === "SOFT_BOUNCE") bounces += n;
    else if (r.type === "COMPLAINT") complaints += n;
  }
  return { sent, delivered, bounces, complaints };
}

async function writeHealthSnapshot(scope: "INBOX" | "DOMAIN", scopeId: string, stats: RateStats, rules: string[], paused: boolean): Promise<void> {
  const day0 = startOfUtcDay();
  const counts: MetricCounts = { ...ZERO_COUNTS, sent: stats.sent, delivered: stats.delivered, hardBounce: stats.bounces, complaints: stats.complaints };
  const score = healthScore(counts);
  const status = paused ? "PAUSED" : healthLevel(score) === "healthy" ? "HEALTHY" : healthLevel(score) === "warning" ? "WARNING" : "DANGER";
  await db.healthSnapshot
    .upsert({
      where: { scope_scopeId_date: { scope, scopeId, date: day0 } },
      create: { scope, scopeId, date: day0, healthScore: score, status, bounceRate: bounceRate(stats), complaintRate: complaintRate(stats), triggeredRules: rules.join(",") },
      update: { healthScore: score, status, bounceRate: bounceRate(stats), complaintRate: complaintRate(stats), triggeredRules: rules.join(",") },
    })
    .catch(() => null);
}

async function evaluateInboxes(thresholds: BurnThresholds): Promise<void> {
  let inboxes;
  try {
    inboxes = await db.inbox.findMany({ where: { status: "ACTIVE" }, select: { id: true } });
  } catch {
    return;
  }
  for (const ib of inboxes) {
    const stats = await statsForScope({ inboxId: ib.id });
    const v = evaluateInboxAutoPause(stats, thresholds);
    await writeHealthSnapshot("INBOX", ib.id, stats, v.rules, v.pause);
    if (v.pause) {
      await db.inbox
        .update({ where: { id: ib.id }, data: { status: v.hardStop ? "BURNING" : "PAUSED", pausedReason: v.reasons.join("; ").slice(0, 400) } })
        .catch(() => null);
      await logEvent("warn", "coldemail.autopause.inbox", { inboxId: ib.id, rules: v.rules, bounceRate: bounceRate(stats) });
    }
  }
}

async function evaluateDomains(thresholds: BurnThresholds): Promise<void> {
  let domains;
  try {
    domains = await db.sendingDomain.findMany({ where: { status: { in: ["ACTIVE", "WARMING"] } }, select: { id: true } });
  } catch {
    return;
  }
  for (const d of domains) {
    const stats = await statsForScope({ sendingDomainId: d.id });
    const v = evaluateDomainAutoPause(stats, thresholds);
    await writeHealthSnapshot("DOMAIN", d.id, stats, v.rules, v.pause);
    if (v.pause) {
      await db.sendingDomain
        .update({ where: { id: d.id }, data: { status: v.hardStop ? "BURNED" : "PAUSED", pausedReason: v.reasons.join("; ").slice(0, 400) } })
        .catch(() => null);
      // Take the domain's inboxes out of rotation too.
      await db.inbox.updateMany({ where: { sendingDomainId: d.id, status: "ACTIVE" }, data: { status: "PAUSED", pausedReason: "Domain auto-paused" } }).catch(() => null);
      await logEvent("warn", "coldemail.autopause.domain", { domainId: d.id, rules: v.rules, complaintRate: complaintRate(stats), bounceRate: bounceRate(stats) });
    }
  }
}

