3169:model SendingDomain {
3206:model Inbox {
3405:model Contact {
3486:model Brand {
3595:model ColdCampaign {
3642:model ColdSend {
3682:model EmailEvent {

model ColdSend {
  id            String         @id @default(cuid())
  campaignId    String
  contactId     String
  // Which sequence step this send is for. Nullable + SetNull so deleting a step
  // never orphans-cascade a historical send; a scheduled (not-yet-sent) send for a
  // removed step is simply left with no step and skipped.
  stepId        String?
  status        ColdSendStatus @default(QUEUED)
  // Phase 3: which Inbox actually sent this message (rotation attribution). Null
  // for legacy/brand-cap sends. SetNull so deleting an inbox never drops history.
  inboxId       String?
  // Phase 2 scheduling + delivery bookkeeping.
  scheduledFor  DateTime?
  sentAt        DateTime?
  messageId     String?
  error         String?
  // Stateless HMAC token embedded in the open pixel + click links for this send.
  trackingToken String?        @unique
  createdAt     DateTime       @default(now())

  campaign ColdCampaign  @relation(fields: [campaignId], references: [id], onDelete: Cascade)
  contact  Contact       @relation(fields: [contactId], references: [id], onDelete: Cascade)
  step     SequenceStep? @relation(fields: [stepId], references: [id], onDelete: SetNull)
  inbox    Inbox?        @relation(fields: [inboxId], references: [id], onDelete: SetNull)
  events   EmailEvent[]
  messages Message[]

  // One send per (campaign, contact, step) — makes the scheduler idempotent: it
  // can re-run without ever double-queuing the same message.
  @@unique([campaignId, contactId, stepId])
  @@index([campaignId])
  @@index([contactId])
  @@index([inboxId])
  @@index([status])
  @@index([scheduledFor])
  @@index([sentAt])
}

/// Immutable tracking event tied to a send. Phase 2 pipeline fills this.
model EmailEvent {
  id        String         @id @default(cuid())
  sendId    String
  type      EmailEventType
  // Optional context — e.g. the clicked URL for a CLICK, or the failure reason for
  // a FAILED. Free text, never trusted for control flow.
  meta      String         @default("")
  createdAt DateTime       @default(now())

  send ColdSend @relation(fields: [sendId], references: [id], onDelete: Cascade)

  @@index([sendId])
  @@index([type])
  @@index([createdAt])
}

// ===========================================================================
// Cold Email Engine — OVERHAUL PHASE 1: the Reply Loop + Master Inbox.
//
// ADDITIVE. Turns the send-only engine into a two-way platform: an IMAP poller
// (worker/coldemail-inbox.ts) captures replies into Conversation/Message, halts
// the contact's remaining sequence sends, and classifies the reply. All inert
// until an Inbox has real IMAP/SMTP credentials — no creds, nothing connects.
// ===========================================================================

/// A reply thread with one contact, seen from one of our inboxes. The unibox's
/// unit. Status starts OPEN and is set by the classifier (or an operator): the
/// interested/not-interested/OOO/auto-reply/unsubscribe buckets a 2026 unibox needs.
enum ConversationStatus {
  OPEN
  REPLIED
  INTERESTED
  NOT_INTERESTED
  AUTO_REPLY
  OUT_OF_OFFICE
  UNSUBSCRIBE
  CLOSED
}

model Brand {
  id                    String    @id @default(cuid())
  name                  String
  fromName              String    @default("")
  fromEmail             String    @default("")
  sendingDomain         String    @default("")
  physicalPostalAddress String    @default("") // CAN-SPAM: valid physical postal address
  replyTo               String    @default("")
  spfVerified           Boolean   @default(false)
  dkimVerified          Boolean   @default(false)
  dmarcVerified         Boolean   @default(false)
  // Phase 2 sending controls.
  // warmupStartedAt anchors the per-inbox warmup ramp (day 1 = a handful/day,
  // growing to the ceiling). null = no warmup started (treated as "still on day 1").
  warmupStartedAt       DateTime?
  // Optional per-brand override of the platform daily cap; null = use the global
  // `coldemail_daily_cap` setting. The cap INCLUDES warmup traffic.
  dailySendCap          Int?
  // Complaint-rate circuit breaker: when tripped the send worker refuses this
  // brand until an operator clears it. `pausedReason` records why.
  sendingPaused         Boolean   @default(false)
  pausedReason          String    @default("")
  createdAt             DateTime  @default(now())

  lists          EmailList[]
  suppressions   Suppression[]
  campaigns      ColdCampaign[]
  sendingDomains SendingDomain[]

  @@index([createdAt])
}

/// A static list of contacts. Optionally scoped to a brand.
model EmailList {
  id          String   @id @default(cuid())
  name        String
  brandId     String?
  description String   @default("")
  createdAt   DateTime @default(now())

  brand         Brand?            @relation(fields: [brandId], references: [id], onDelete: SetNull)
  members       EmailListMember[]
  campaigns     ColdCampaign[]
  importBatches ImportBatch[]

  @@index([brandId])
  @@index([createdAt])
}

/// Membership edge: one contact on one list.
model EmailListMember {
  id        String   @id @default(cuid())
  listId    String
  contactId String
  createdAt DateTime @default(now())

  list    EmailList @relation(fields: [listId], references: [id], onDelete: Cascade)
  contact Contact   @relation(fields: [contactId], references: [id], onDelete: Cascade)

  @@unique([listId, contactId])
  @@index([contactId])
}

/// The suppression list — the core of the compliance layer. A row targets an
/// `email` OR a `domain`. Checked against every recipient at preview time and
/// (in Phase 2) at send time.
model Suppression {
  id        String            @id @default(cuid())
  email     String?
  domain    String?
  reason    SuppressionReason @default(MANUAL)
  scope     SuppressionScope  @default(GLOBAL)
  brandId   String?
  createdAt DateTime          @default(now())

  brand Brand? @relation(fields: [brandId], references: [id], onDelete: Cascade)

  // De-dupe within a scope/brand. NULL brandId rows (GLOBAL) rely on the
  // unsubscribe/import actions to check-then-insert for idempotency, since
  // Postgres treats NULLs as distinct in a unique index.
  @@unique([scope, brandId, email])
  @@unique([scope, brandId, domain])
  @@index([email])
  @@index([domain])
  @@index([scope])
}

/// Documented lawful basis for contacting a person. Append-only audit record.
model ConsentRecord {
  id            String       @id @default(cuid())
  contactId     String
  basis         ConsentBasis @default(LEGITIMATE_INTEREST)
  jurisdiction  String       @default("")
  source        String       @default("")
  // Reference to a documented Legitimate Interest Assessment (GDPR) or the
  // existing-relationship evidence (CASL). Phase 3, additive.
  assessmentRef String       @default("")
  note          String       @default("")
  createdAt     DateTime     @default(now())

  contact Contact @relation(fields: [contactId], references: [id], onDelete: Cascade)

  @@index([contactId])
  @@index([createdAt])
}

/// A campaign. Phase 1 creates these as DRAFT only; the sequence steps hang off
/// it. `ColdCampaign` (not `Campaign`) to avoid colliding with any future
/// platform campaign concept.
model ColdCampaign {
  id              String             @id @default(cuid())
  brandId         String
  name            String
  listId          String
  status          ColdCampaignStatus @default(DRAFT)

// Cold Email Engine — sending transport + message rendering (Phase 2).
//
// This module has TWO halves:
//
//   1. PURE rendering (`renderStepBody`, `buildMessage`, `injectTracking`,
//      markdown → HTML). No I/O, no DB, no network — the send worker AND the test
//      suite call these identically. Importing this module never opens a socket.
//
//   2. A pluggable `MailTransport` interface with a Nxeon Mail SMTP adapter
//      (reusing the platform's SMTP Setting mechanism from lib/mailer.ts) and an
//      SES adapter SEAM for later. Only `NxeonSmtpTransport.send()` touches the
//      network, and it is only ever reached from the send worker, which is hard-
//      gated behind the `cold_email_sending_enabled` kill-switch.
//
// SAFETY: nothing here checks the kill-switch or the suppression list itself —
// those gates live in the worker so they are enforced once, at the choke point,
// immediately before each send. This module assumes the caller has already
// cleared a message to send.

import nodemailer from "nodemailer";
import { wrapEmail, appUrl } from "@/lib/email-render";
import {
  complianceFooter,
  unsubscribeToken,
  openTrackingToken,
  clickTrackingToken,
  normalizeDomain,
  type BrandLike,
} from "@/lib/coldemail/compliance";

// ---------------------------------------------------------------------------
// Shapes
// ---------------------------------------------------------------------------

export type SendIdentity = BrandLike & {
  id: string;
  name?: string | null;
  fromName?: string | null;
  fromEmail?: string | null;
  replyTo?: string | null;
  sendingDomain?: string | null;
};

export type StepLike = { subject: string; bodyMarkdown: string };

export type ContactLike = {
  id: string;
  email: string;
  fullName?: string | null;
  title?: string | null;
  business?: { name?: string | null } | null;
};

export type RenderedMessage = {
  from: string;
  to: string;
  replyTo?: string;
  subject: string;
  html: string;
  text: string;
  headers: Record<string, string>;
};

export type SendResult = { messageId?: string };

/** A transport is anything that can put one fully-rendered message on the wire. */
export interface MailTransport {
  readonly name: string;
  send(msg: RenderedMessage): Promise<SendResult>;
}

// ---------------------------------------------------------------------------
// Minimal, dependency-free markdown → HTML (no `marked` in this repo).
// Supports: paragraphs, line breaks, **bold**, *italic*, [text](url), and bare
// autolinks. Everything is escaped first, so raw HTML in the body is inert.
// ---------------------------------------------------------------------------

function esc(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

/** Render a markdown body to safe inline-styled HTML paragraphs. */
export function markdownToHtml(md: string): string {
  const inline = (raw: string): string => {
    let s = esc(raw);
    // [label](http…) links — label and URL are already escaped.
    s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (_m, label, url) => {
      return `<a href="${url}" style="color:#6f47f5;text-decoration:underline;">${label}</a>`;
    });
    // Bare autolinks not already inside an <a href="…">.
    s = s.replace(/(^|[\s(])((https?:\/\/[^\s<)]+))/g, (_m, pre, url) => {
      return `${pre}<a href="${url}" style="color:#6f47f5;text-decoration:underline;">${url}</a>`;
    });
    s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    s = s.replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>");
    return s;
  };

  const paragraphs = String(md ?? "")
    .replace(/\r\n?/g, "\n")
    .split(/\n{2,}/)
    .map((p) => p.trim())
    .filter(Boolean)
    .map((p) => {
      const body = p.split("\n").map(inline).join("<br/>");
      return `<p style="margin:0 0 16px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#4a4763;">${body}</p>`;
    });
  return paragraphs.join("\n");
}

// ---------------------------------------------------------------------------
// Variable substitution for personalization tokens ({{firstName}}, {{company}}…)
// ---------------------------------------------------------------------------

export function contactVars(contact: ContactLike): Record<string, string> {
  const full = (contact.fullName ?? "").trim();
  const firstName = full.split(/\s+/)[0] ?? "";
  return {
    firstName,
    fullName: full,
    title: (contact.title ?? "").trim(),
    email: contact.email,
    company: (contact.business?.name ?? "").trim(),
  };
}

function substitute(input: string, vars: Record<string, string>): string {
  return String(input ?? "").replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, key: string) =>
    vars[key] !== undefined ? vars[key] : "",
  );
}

// ---------------------------------------------------------------------------
// Tracking injection (open pixel + click-through rewriting). PURE.
// ---------------------------------------------------------------------------

export function openPixelUrl(base: string, sendId: string): string {
  return `${base.replace(/\/$/, "")}/api/coldemail/track/open/${openTrackingToken(sendId)}`;
}

export function clickWrapUrl(base: string, sendId: string, target: string): string {
  return `${base.replace(/\/$/, "")}/api/coldemail/track/click/${clickTrackingToken(sendId, target)}`;
}

/**
 * Rewrite outbound `<a href="http…">` links through the click-tracking redirect
 * and append a 1x1 open pixel. Applied ONLY at send time — previews never call
 * this, so an operator's preview shows real, unwrapped links. The unsubscribe
 * link is deliberately left un-wrapped: it must remain a direct, one-click,
 * no-JS, no-redirect target per RFC 8058.
 */
export function injectTracking(html: string, sendId: string, base: string, opts: { skip?: (url: string) => boolean } = {}): string {
  const skip = opts.skip ?? (() => false);
  const rewritten = html.replace(/href="(https?:\/\/[^"]+)"/gi, (m, url: string) => {
    if (skip(url)) return m;
    return `href="${clickWrapUrl(base, sendId, url)}"`;
  });
  const pixel = `<img src="${openPixelUrl(base, sendId)}" width="1" height="1" alt="" style="display:none;width:1px;height:1px;border:0;" />`;
  return `${rewritten}\n${pixel}`;
}

// ---------------------------------------------------------------------------
// Message rendering (PURE — the heart the tests exercise)
// ---------------------------------------------------------------------------

/** Build the `From` header value from a brand identity. */
export function fromHeader(identity: SendIdentity): string {
  const email = (identity.fromEmail ?? "").trim();
  const name = (identity.fromName ?? identity.name ?? "").trim();
  return name ? `${name} <${email}>` : email;
}

/** The From domain used for reputation-isolation checks. */
export function identityDomain(identity: SendIdentity): string {
  return normalizeDomain(identity.sendingDomain) || normalizeDomain(identity.fromEmail);
}

export type BuildMessageOpts = {
  identity: SendIdentity;
  step: StepLike;
  contact: ContactLike;
  /** ColdSend id — anchors tracking tokens. Omit for a plain preview. */
  sendId?: string;
  /** Base URL for links (defaults to appUrl()). */
  base?: string;
  /** Extra disclosure line appended under the required footer. */
  footerDisclosure?: string;
  /** Inject open pixel + click tracking. FALSE for previews. */
  track?: boolean;
};

/**
 * Render one SequenceStep into a fully-formed, compliant message:
 *  - subject + markdown body with {{tokens}} substituted,
 *  - the mandatory compliance footer (postal address + one-click unsubscribe),
 *  - `List-Unsubscribe` + `List-Unsubscribe-Post` headers (RFC 8058),
 *  - open/click tracking when `track` and a `sendId` are supplied.
 *
 * No network, no DB — deterministic given its inputs.
 */
export function buildMessage(opts: BuildMessageOpts): RenderedMessage {
  const { identity, step, contact } = opts;
  const base = (opts.base ?? appUrl()).replace(/\/$/, "");
  const vars = contactVars(contact);

  const subject = substitute(step.subject, vars);

  // Unsubscribe target (RFC 8058 one-click). Same HMAC token the endpoint verifies.
  const unsubToken = unsubscribeToken(contact.id, identity.id);
  const unsubscribeUrl = `${base}/api/coldemail/unsubscribe?token=${unsubToken}`;

  // Body: markdown → HTML, then the mandatory footer as an HTML block.
  const bodyHtml = markdownToHtml(substitute(step.bodyMarkdown, vars));
  const footerText = complianceFooter(identity, unsubscribeUrl);
  const disclosure = (opts.footerDisclosure ?? "").trim();
  const footerHtml = renderFooterHtml(identity, unsubscribeUrl, disclosure);

  let contentHtml = `${bodyHtml}\n${footerHtml}`;
  if (opts.track && opts.sendId) {
    contentHtml = injectTracking(contentHtml, opts.sendId, base, {
      // Never route the unsubscribe link through click-tracking.
      skip: (url) => url.includes("/api/coldemail/unsubscribe"),
    });
  }

  const html = wrapEmail(contentHtml, { preheader: subject });
  const text = buildPlainText(substitute(step.bodyMarkdown, vars), footerText);

  const headers: Record<string, string> = {
    // RFC 8058: HTTPS one-click unsubscribe. The POST target and the GET are the
    // same URL; the endpoint honours the POST immediately.
    "List-Unsubscribe": `<${unsubscribeUrl}>`,
    "List-Unsubscribe-Post": "List-Unsubscribe=One-Click",
    // Bulk-sender hygiene — a stable, honest precedence marker.
    "X-Nxeon-Cold-Email": "1",
  };

  return {
    from: fromHeader(identity),
    to: contact.email,
    replyTo: (identity.replyTo ?? "").trim() || undefined,
    subject,
    html,
    text,
    headers,
  };
}

/** The compliance footer, styled as an HTML block for the email body. */
function renderFooterHtml(identity: SendIdentity, unsubscribeUrl: string, disclosure: string): string {
  const address = (identity.physicalPostalAddress ?? "").trim() || "[physical postal address not set]";
  const parts = [
    disclosure ? esc(disclosure) : "You are receiving this message as a business contact.",
    `Our postal address: ${esc(address)}`,
    `To stop receiving these emails, <a href="${unsubscribeUrl}" style="color:#8a86a3;text-decoration:underline;">unsubscribe here</a>.`,
  ];
  return `<div style="margin-top:28px;padding-top:16px;border-top:1px solid #ecebf3;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:12px;line-height:1.6;color:#8a86a3;">${parts.join("<br/>")}</div>`;
}

/** Plain-text alternative: markdown stripped of decoration + the footer text. */
function buildPlainText(bodyMarkdown: string, footerText: string): string {
  const body = String(bodyMarkdown ?? "")
    .replace(/\r\n?/g, "\n")
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, "$1 ($2)")
    .replace(/\*\*([^*]+)\*\*/g, "$1")
    .replace(/\*([^*]+)\*/g, "$1")
    .trim();
  return `${body}\n\n---\n${footerText}\n`;
}

// ---------------------------------------------------------------------------
// Transports
// ---------------------------------------------------------------------------

type SmtpConfig = {
  host: string;
  port: number;
  user: string;
  pass: string;
  secure: boolean;
};

/**
 * Load the platform SMTP settings the same way lib/mailer.ts does — the same
 * Setting rows (smtp_host/port/user/pass/secure), the same encrypted-password
 * tolerance, the same env fallback. Loaded lazily so importing this module never
 * touches the DB (keeps the module unit-testable and side-effect-free).
 */
async function loadSmtpConfig(): Promise<SmtpConfig> {
  const { db } = await import("@/lib/db");
  const { decryptSecret } = await import("@/lib/crypto-box");
  const rows = await db.setting.findMany({
    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_secure"] } },
  });
  const s = Object.fromEntries(rows.map((r) => [r.key, r.value])) as Record<string, string>;
  const storedPass = s.smtp_pass;
  const pass = storedPass ? decryptSecret(storedPass) ?? storedPass : process.env.SMTP_PASS || "";
  return {
    host: s.smtp_host || process.env.SMTP_HOST || "",
    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
    user: s.smtp_user || process.env.SMTP_USER || "",
    pass,
    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
  };
}

/**
 * Nxeon Mail (Mailcow) SMTP transport. The From identity is per-brand (passed on
 * each message) rather than the platform's transactional `smtp_from`, so a cold
 * campaign always sends as its dedicated sending identity — never as the platform.
 */
export class NxeonSmtpTransport implements MailTransport {
  readonly name = "nxeon-smtp";
  constructor(private readonly cfg: SmtpConfig) {}

  private transporter() {
    if (!this.cfg.host) {
      return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
    }
    const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
    return nodemailer.createTransport({
      host: this.cfg.host,
      port: this.cfg.port,
      secure: this.cfg.secure,
      auth: this.cfg.user ? { user: this.cfg.user, pass: this.cfg.pass } : undefined,
      ...(servername ? { tls: { servername } } : {}),
    });
  }

  async send(msg: RenderedMessage): Promise<SendResult> {
    const info = await this.transporter().sendMail({
      from: msg.from,
      to: msg.to,
      replyTo: msg.replyTo,
      subject: msg.subject,
      html: msg.html,
      text: msg.text,
      headers: msg.headers,
    });
    return { messageId: (info as { messageId?: string })?.messageId };
  }
}

/**
 * Amazon SES adapter SEAM. Left as a stub because SES is not provisioned yet and
 * this phase must not add dependencies or send anything. When a brand's domain
 * lives on SES, wire the AWS SDK here behind the same interface — the worker code
 * does not change.
 */
export class SesTransport implements MailTransport {
  readonly name = "ses";
  async send(_msg: RenderedMessage): Promise<SendResult> {
    throw new Error(
      "SES transport is not configured. The cold-email engine currently sends only via Nxeon Mail (SMTP). " +
        "Provision SES + wire the AWS SDK into SesTransport.send before selecting it.",
    );
  }
}

export type TransportKind = "nxeon-smtp" | "ses";

/**
 * Resolve the transport for a send. Defaults to Nxeon Mail SMTP. Async because
 * building the SMTP transport reads the Setting rows; kept off the module's import
 * path so tests can import the pure renderers without a DB.
 */
export async function getTransport(kind: TransportKind = "nxeon-smtp"): Promise<MailTransport> {
  if (kind === "ses") return new SesTransport();
  return new NxeonSmtpTransport(await loadSmtpConfig());
}

