import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { verifyOpenToken } from "@/lib/coldemail/compliance";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

/**
 * Open-tracking pixel. Verifies the HMAC token, records an OPEN EmailEvent for the
 * send, and always returns a 1x1 transparent GIF (even on a bad token) so a broken
 * or replayed link never shows a broken-image icon in a recipient's inbox.
 *
 * Never throws, never blocks: a tracking write failing must not fail the pixel.
 */

// 1x1 transparent GIF.
const PIXEL = Buffer.from("R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7", "base64");

function gif(): Response {
  return new NextResponse(new Uint8Array(PIXEL), {
    status: 200,
    headers: {
      "Content-Type": "image/gif",
      "Content-Length": String(PIXEL.length),
      "Cache-Control": "no-store, no-cache, must-revalidate, private",
      Pragma: "no-cache",
    },
  });
}

export async function GET(_req: Request, { params }: { params: Promise<{ token: string }> }) {
  const { token } = await params;
  const sendId = verifyOpenToken(token);
  if (sendId) {
    try {
      const send = await db.coldSend.findUnique({ where: { id: sendId }, select: { id: true } });
      if (send) await db.emailEvent.create({ data: { sendId, type: "OPEN" } });
    } catch {
      /* tracking is best-effort — always return the pixel */
    }
  }
  return gif();
}
