import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { verifyClickToken } from "@/lib/coldemail/compliance";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

/**
 * Click-tracking redirect. The destination URL is carried INSIDE the HMAC-signed
 * token (see clickTrackingToken), so an attacker cannot turn this into an open
 * redirect by swapping the target — an unsigned/tampered token 400s instead of
 * redirecting. verifyClickToken additionally requires an absolute http(s) URL.
 *
 * On a valid token it records a CLICK EmailEvent (best-effort) then 302s to the
 * real destination.
 */
export async function GET(_req: Request, { params }: { params: Promise<{ token: string }> }) {
  const { token } = await params;
  const claims = verifyClickToken(token);
  if (!claims) {
    return NextResponse.json({ error: "Invalid or expired link." }, { status: 400 });
  }
  try {
    const send = await db.coldSend.findUnique({ where: { id: claims.sendId }, select: { id: true } });
    if (send) await db.emailEvent.create({ data: { sendId: claims.sendId, type: "CLICK", meta: claims.url.slice(0, 300) } });
  } catch {
    /* tracking is best-effort — still redirect */
  }
  return NextResponse.redirect(claims.url, 302);
}

// Cold Email Engine — deliverability analytics (Phase 3).
//
// PURE + unit-testable: NO database access, NO I/O. Turns raw event counts into
// the derived rates the dashboards show, and — critically — encodes the 2026
// HONESTY posture about open tracking:
//
//   Apple Mail Privacy Protection pre-loads tracking pixels on Apple's servers,
//   so 50%+ of "opens" are machine-generated. Open rate is therefore surfaced but
//   flagged UNRELIABLE and MUST NOT be a health signal or optimization target.
//   The primary signals are reply / positive-reply, bounce, complaint, click,
//   unsubscribe, and inbox-placement (from seed tests).
//
// The worker rolls DeliverabilityEvent rows into MetricsDaily; this module derives
// the rates from those counts and colours them against the research benchmarks.

// ---------------------------------------------------------------------------
// Counts + derived rates
// ---------------------------------------------------------------------------

/** Raw daily counts for one scope (campaign / inbox / domain / brand). */
export type MetricCounts = {
  sent: number;
  delivered: number;
  hardBounce: number;
  softBounce: number;
  /** UNRELIABLE — MPP/scanner-inflated. Never a health signal. */
  opens: number;
  uniqueClicks: number;
  replies: number;
  positiveReplies: number;
  complaints: number;
  unsubscribes: number;
};

export const ZERO_COUNTS: MetricCounts = {
  sent: 0,
  delivered: 0,
  hardBounce: 0,
  softBounce: 0,
  opens: 0,
  uniqueClicks: 0,
  replies: 0,
  positiveReplies: 0,
  complaints: 0,
  unsubscribes: 0,
};

export type DerivedRates = {
  deliveryRate: number;
  bounceRate: number; // (hard+soft)/sent
  hardBounceRate: number;
  complaintRate: number; // complaints/delivered
  unsubRate: number;
  clickRate: number;
  replyRate: number;
  positiveReplyRate: number;
  /** UNRELIABLE — surfaced for context only, flagged everywhere it appears. */
  openRate: number;
};

const safeDiv = (a: number, b: number) => (b > 0 ? a / b : 0);

/** Add two count buckets — used when rolling many event rows into one daily row. */
export function addCounts(a: MetricCounts, b: Partial<MetricCounts>): MetricCounts {
  const out = { ...a };
  for (const k of Object.keys(ZERO_COUNTS) as (keyof MetricCounts)[]) {
    out[k] = (a[k] ?? 0) + (b[k] ?? 0);
  }
  return out;
}

/**
 * Derive every rate from a count bucket. Delivered is the denominator for the
 * engagement/complaint rates (they only make sense over accepted mail); bounce is
 * over sent. Divide-by-zero is 0, never NaN.
 */
export function deriveRates(m: MetricCounts): DerivedRates {
  const bounces = (m.hardBounce ?? 0) + (m.softBounce ?? 0);
  return {
    deliveryRate: safeDiv(m.delivered, m.sent),
    bounceRate: safeDiv(bounces, m.sent),
    hardBounceRate: safeDiv(m.hardBounce, m.sent),
    complaintRate: safeDiv(m.complaints, m.delivered),
    unsubRate: safeDiv(m.unsubscribes, m.delivered),
    clickRate: safeDiv(m.uniqueClicks, m.delivered),
    replyRate: safeDiv(m.replies, m.delivered),
    positiveReplyRate: safeDiv(m.positiveReplies, m.delivered),
    openRate: safeDiv(m.opens, m.delivered),
  };
}

// ---------------------------------------------------------------------------
// Open-rate honesty (surfaced by every UI that shows an open number)
// ---------------------------------------------------------------------------

export const OPEN_RATE_UNRELIABLE = true;
export const OPEN_RATE_LABEL = "Open rate (unreliable)";
export const OPEN_RATE_WARNING =
  "Unreliable (MPP-inflated) — do not optimize on this. Apple Mail Privacy Protection auto-opens 50%+ of email and corporate scanners pre-fetch pixels, so opens are machine-generated noise.";

/** The signals leaders actually optimise on in 2026 (research §4). */
export const PRIMARY_SIGNALS = [
  "positiveReplyRate",
  "replyRate",
  "bounceRate",
  "complaintRate",
  "clickRate",
  "unsubRate",
  "inboxPlacementRate",
] as const;

// ---------------------------------------------------------------------------
// Benchmark bands (research §4) → red/amber/green
// ---------------------------------------------------------------------------

export type Band = "green" | "amber" | "red";

/** Bounce: <2% green · 2–5% amber · >5% red (research §4). */
export function bounceBand(rate: number): Band {
  if (rate < 0.02) return "green";
  if (rate < 0.05) return "amber";
  return "red";
}

/** Complaint: <0.05% green · 0.05–0.08% amber · >0.08% red (research §4). */
export function complaintBand(rate: number): Band {
  if (rate < 0.0005) return "green";
  if (rate < 0.0008) return "amber";
  return "red";
}

/** Inbox placement: ≥90% green · 80–90% amber · <80% red (research §4). */
export function placementBand(rate: number): Band {
  if (rate >= 0.9) return "green";
  if (rate >= 0.8) return "amber";
  return "red";
}

// ---------------------------------------------------------------------------
// Inbox-placement (seed test) result
// ---------------------------------------------------------------------------

export type PlacementResult = {
  inboxPct: number;
  spamPct: number;
  promotionsPct: number;
  missingPct: number;
};

/** Normalise seed-test percentages to fractions summing ≤1 (defensive). */
export function normalizePlacement(p: Partial<PlacementResult>): PlacementResult {
  const f = (v: unknown) => {
    let n = Number(v);
    if (!Number.isFinite(n) || n < 0) n = 0;
    if (n > 1) n = n / 100; // accept whole-percent inputs
    return Math.min(1, n);
  };
  return {
    inboxPct: f(p.inboxPct),
    spamPct: f(p.spamPct),
    promotionsPct: f(p.promotionsPct),
    missingPct: f(p.missingPct),
  };
}

// ---------------------------------------------------------------------------
// Composite health score (0–100) — deliberately excludes open rate
// ---------------------------------------------------------------------------

/**
 * A 0–100 health score from the MPP-proof signals only: bounce, complaint and
 * unsubscribe penalise; a healthy reply rate lifts. Opens are NEVER an input —
 * that is the whole point. Placement (when known) pulls the score toward the
 * seed-test truth. Returns 100 when there is no volume to judge.
 */
export function healthScore(m: MetricCounts, placement?: PlacementResult | null): number {
  if (m.sent <= 0) return 100;
  const r = deriveRates(m);
  let score = 100;
  // Bounce: every 1% over 0 costs ~12 points (5% ≈ -60).
  score -= Math.min(60, (r.bounceRate / 0.01) * 12);
  // Complaint: brutal — 0.1% ≈ -30, 0.3% ≈ -90.
  score -= Math.min(90, (r.complaintRate / 0.001) * 30);
  // Unsubscribe: mild disengagement signal.
  score -= Math.min(15, (r.unsubRate / 0.01) * 5);
  // Reply rate rewards genuine engagement (cap +10).
  score += Math.min(10, (r.replyRate / 0.02) * 5);
  if (placement) {
    // Blend 30% toward measured inbox placement when we have a seed test.
    score = score * 0.7 + placement.inboxPct * 100 * 0.3;
  }
  return Math.max(0, Math.min(100, Math.round(score)));
}

export type HealthLevel = "healthy" | "warning" | "danger";

/** Map a composite health score to a status band for badges/colours. */
export function healthLevel(score: number): HealthLevel {
  if (score >= 75) return "healthy";
  if (score >= 50) return "warning";
  return "danger";
}

/** Format a fraction as a percent string for display (e.g. 0.0123 → "1.23%"). */
export function formatPct(rate: number, dp = 2): string {
  if (!Number.isFinite(rate)) return "—";
  return `${(rate * 100).toFixed(dp)}%`;
}

// Cold Email Engine — per-BUSINESS engagement readout.
//
// Answers the operator question "which specific businesses opened or clicked this
// campaign?" by walking the tracking data that already lands on our own server:
//
//   EmailEvent(OPEN|CLICK)  →  ColdSend  →  Contact  →  Business
//
// Every open pixel hit and every click redirect writes an EmailEvent tied to the
// send; the send knows the contact; the contact knows the business. So attribution
// is a pure read — no schema change, no external data. Server-only (imports db).

import { db } from "@/lib/db";

export type EngagementRow = {
  sendId: string;
  contactId: string;
  businessName: string;
  email: string;
  city: string;
  region: string;
  category: string;
  website: string;
  sentAt: Date | null;
  opens: number;
  lastOpenAt: Date | null;
  clicks: number;
  lastClickAt: Date | null;
  lastClickUrl: string;
  replied: boolean;
  /** Most recent of lastOpenAt / lastClickAt — used to sort "hottest first". */
  lastActivityAt: Date | null;
};

export type CampaignEngagement = {
  rows: EngagementRow[];
  engagedCount: number; // distinct businesses with >=1 open or click
  totalOpens: number;
  totalClicks: number;
  clickedCount: number; // distinct businesses with >=1 click (the hottest leads)
  truncated: boolean; // true if more engaged recipients exist than `rows` shows
};

/**
 * Build the engaged-recipient table for a campaign. Only recipients with at least
 * one OPEN or CLICK are returned (that's the "who engaged" question); they're
 * sorted hottest-first — clickers above openers, then by most recent activity.
 *
 * `limit` bounds the number of rows rendered (default 250). `engagedCount` is the
 * true distinct total so the UI can say "showing 250 of 1,032".
 */
export async function campaignEngagement(
  campaignId: string,
  opts: { limit?: number } = {},
): Promise<CampaignEngagement> {
  const limit = Math.max(1, Math.min(opts.limit ?? 250, 2000));

  // Pull the OPEN/CLICK events for this campaign (newest first). Bounded so a very
  // large campaign can't blow memory — we aggregate per send below.
  const events = await db.emailEvent.findMany({
    where: { type: { in: ["OPEN", "CLICK"] }, send: { campaignId } },
    select: { sendId: true, type: true, meta: true, createdAt: true },
    orderBy: { createdAt: "desc" },
    take: 20000,
  });

  if (events.length === 0) {
    return { rows: [], engagedCount: 0, totalOpens: 0, totalClicks: 0, clickedCount: 0, truncated: false };
  }

  // Aggregate per send (events already newest-first, so the first CLICK we see per
  // send is the most recent one).
  type Agg = {
    opens: number;
    clicks: number;
    lastOpenAt: Date | null;
    lastClickAt: Date | null;
    lastClickUrl: string;
  };
  const bySend = new Map<string, Agg>();
  let totalOpens = 0;
  let totalClicks = 0;
  for (const e of events) {
    let a = bySend.get(e.sendId);
    if (!a) {
      a = { opens: 0, clicks: 0, lastOpenAt: null, lastClickAt: null, lastClickUrl: "" };
      bySend.set(e.sendId, a);
    }
    if (e.type === "OPEN") {
      a.opens++;
      totalOpens++;
      if (!a.lastOpenAt) a.lastOpenAt = e.createdAt; // newest-first ⇒ first seen = latest
    } else {
      a.clicks++;
      totalClicks++;
      if (!a.lastClickAt) {
        a.lastClickAt = e.createdAt;
        a.lastClickUrl = e.meta ?? "";
      }
    }
  }

  const engagedCount = bySend.size;
  const clickedCount = [...bySend.values()].filter((a) => a.clicks > 0).length;

  // Fetch the sends (with contact + business) for the engaged set. Cap the DB hit
  // at the sends we'll actually rank; we rank in JS then slice to `limit`.
  const sendIds = [...bySend.keys()];
  const sends = await db.coldSend.findMany({
    where: { id: { in: sendIds } },
    select: {
      id: true,
      sentAt: true,
      contactId: true,
      contact: {
        select: {
          email: true,
          repliedAt: true,
          business: { select: { name: true, city: true, region: true, category: true, website: true } },
        },
      },
    },
  });

  const rows: EngagementRow[] = sends.map((s) => {
    const a = bySend.get(s.id)!;
    const b = s.contact.business;
    const lastActivityAt =
      a.lastClickAt && a.lastOpenAt
        ? a.lastClickAt > a.lastOpenAt
          ? a.lastClickAt
          : a.lastOpenAt
        : a.lastClickAt ?? a.lastOpenAt;
    return {
      sendId: s.id,
      contactId: s.contactId,
      businessName: b?.name ?? "",
      email: s.contact.email,
      city: b?.city ?? "",
      region: b?.region ?? "",
      category: b?.category ?? "",
      website: b?.website ?? "",
      sentAt: s.sentAt,
      opens: a.opens,
      lastOpenAt: a.lastOpenAt,
      clicks: a.clicks,
      lastClickAt: a.lastClickAt,
      lastClickUrl: a.lastClickUrl,
      replied: s.contact.repliedAt != null,
      lastActivityAt,
    };
  });

  // Hottest first: clickers before pure-openers, then most-recent activity.
  rows.sort((x, y) => {
    if ((y.clicks > 0 ? 1 : 0) !== (x.clicks > 0 ? 1 : 0)) return (y.clicks > 0 ? 1 : 0) - (x.clicks > 0 ? 1 : 0);
    const xa = x.lastActivityAt?.getTime() ?? 0;
    const ya = y.lastActivityAt?.getTime() ?? 0;
    return ya - xa;
  });

  const truncated = rows.length > limit || events.length >= 20000;
  return {
    rows: rows.slice(0, limit),
    engagedCount,
    totalOpens,
    totalClicks,
    clickedCount,
    truncated,
  };
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, EmptyState } from "@/components/ui/primitives";
import { SeedTestForm, DeliverabilitySignalForm } from "@/components/admin/coldemail/Phase3Controls";
import {
  deriveRates,
  addCounts,
  ZERO_COUNTS,
  formatPct,
  bounceBand,
  complaintBand,
  placementBand,
  OPEN_RATE_WARNING,
  type MetricCounts,
  type Band,
} from "@/lib/coldemail/analytics";

export const dynamic = "force-dynamic";

const WINDOW_DAYS = 30;
const bandText: Record<Band, string> = { green: "text-emerald-300", amber: "text-amber-300", red: "text-red-300" };

function Tile({ label, value, band, hint }: { label: string; value: string; band?: Band; hint?: string }) {
  return (
    <div className="card p-4">
      <p className="text-[13px] text-slate-400">{label}</p>
      <p className={`mt-1 text-2xl font-bold ${band ? bandText[band] : "text-slate-100"}`}>{value}</p>
      {hint && <p className="mt-1 text-xs text-slate-500">{hint}</p>}
    </div>
  );
}

