import { NextResponse } from "next/server";
import { db } from "@/lib/db";

// 1x1 transparent GIF — the smallest valid image, so the "load" completes
// instantly and never renders anything visible even if an unusually permissive
// mail client shows broken-image alt text otherwise.
const PIXEL = Buffer.from("R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBTAA7", "base64");

const PIXEL_HEADERS = {
  "Content-Type": "image/gif",
  "Content-Length": String(PIXEL.length),
  // Never cached — a mail client (or its image proxy) caching this would
  // silently stop pinging us on repeat opens.
  "Cache-Control": "no-store, no-cache, must-revalidate, private",
  Pragma: "no-cache",
};

/**
 * Email open-tracking pixel. GET-only, unauthenticated by necessity — mail
 * clients fetch `<img>` tags with no credentials of any kind. Always returns
 * the pixel even when the DB update fails or `id` doesn't match any row: a
 * tracking miss must never look like a broken image to the recipient.
 */
export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  try {
    await db.emailLog.updateMany({
      where: { id },
      data: { openCount: { increment: 1 } },
    });
    // Separate call so `openedAt` is set only on the FIRST open (a raw
    // increment has no "only if null" form) — cheap given how rarely a given
    // pixel is hit at all, let alone twice in the same instant.
    await db.emailLog.updateMany({
      where: { id, openedAt: null },
      data: { openedAt: new Date() },
    });
  } catch {
    // Best-effort — the pixel must render regardless.
  }
  return new NextResponse(PIXEL, { headers: PIXEL_HEADERS });
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { appUrl } from "@/lib/email-render";

/**
 * Email click-tracking redirect. GET-only, unauthenticated by necessity (the
 * recipient is clicking from their mail client, not a logged-in browser tab).
 *
 * `idx` is a positional index into the EmailLog row's own `links` array —
 * NEVER a client-supplied URL. lib/mailer.ts populates that array at send
 * time from the email's own real anchors (minus anything secret-bearing), so
 * this route can only ever redirect somewhere WE put in that specific email.
 * That is a deliberate design choice, not an oversight: a click endpoint that
 * instead took `?u=<url>` would be a textbook open redirect — usable to
 * launder an arbitrary destination behind a trusted nxeon.cloud link.
 */
export async function GET(
  _req: Request,
  { params }: { params: Promise<{ id: string; idx: string }> },
) {
  const { id, idx } = await params;
  const i = Number(idx);
  const fallback = NextResponse.redirect(appUrl(), 302);

  if (!Number.isInteger(i) || i < 0) return fallback;

  try {
    const row = await db.emailLog.findUnique({ where: { id }, select: { links: true } });
    const links = Array.isArray(row?.links) ? (row.links as unknown[]) : null;
    const target = links && typeof links[i] === "string" ? (links[i] as string) : null;
    if (!target) return fallback;

    await db.emailLog.updateMany({
      where: { id },
      data: { clickCount: { increment: 1 } },
    });
    await db.emailLog.updateMany({
      where: { id, clickedAt: null },
      data: { clickedAt: new Date() },
    });

    return NextResponse.redirect(target, 302);
  } catch {
    return fallback;
  }
}

