// Cold Email Engine — tracking-event persistence (open pixel + click redirect).
//
// Shared by app/api/coldemail/track/open/[token] and .../click/[token]. Both
// routes serve an unauthenticated GET straight to a recipient's mail client, so
// every write here is best-effort and never throws — a DB hiccup must never turn
// into a broken pixel or a failed redirect.
//
// Three things happen per event:
//   1. an immutable EmailEvent(OPEN|CLICK) row — the per-event history that
//      lib/coldemail/engagement.ts already reads for the campaign "who engaged"
//      table (app/admin/coldemail/campaigns/[id]).
//   2. denormalized openedAt/openCount (clickedAt/clickCount) on the ColdSend row
//      itself — the same shape as EmailLog's tracking columns (see
//      manual-migration-emaillog-tracking.sql / manual-migration-coldsend-
//      tracking.sql), for cheap per-send lookups without joining EmailEvent.
//   3. a DeliverabilityEvent row. THIS WAS THE MISSING PIECE: the pixel/redirect
//      routes previously wrote only the EmailEvent, but
//      worker/coldemail-deliverability.ts's rollup sweep aggregates MetricsDaily
//      exclusively from DeliverabilityEvent (see EVENT_TO_COUNT in that file,
//      which already had OPEN/CLICK mapped — it just never received any). Without
//      this write, every open/click tile on the admin analytics page
//      (app/admin/coldemail/analytics) would stay at 0% forever even with real
//      engagement happening.

import { db } from "@/lib/db";

async function loadSendContext(sendId: string) {
  return db.coldSend.findUnique({
    where: { id: sendId },
    select: {
      id: true,
      campaignId: true,
      contactId: true,
      inboxId: true,
      inbox: { select: { sendingDomainId: true } },
    },
  });
}

/** Record one OPEN for `sendId`. Returns false (no-op) if the send doesn't exist. */
export async function recordOpenEvent(sendId: string): Promise<boolean> {
  const send = await loadSendContext(sendId).catch(() => null);
  if (!send) return false;

  await db.emailEvent.create({ data: { sendId, type: "OPEN" } }).catch(() => null);

  // openCount always increments; openedAt only stamps on the FIRST open (a raw
  // increment has no "only if null" form) — same two-call pattern as EmailLog's
  // /api/track/email/[id]/open route.
  await db.coldSend
    .update({ where: { id: sendId }, data: { openCount: { increment: 1 } } })
    .catch(() => null);
  await db.coldSend
    .updateMany({ where: { id: sendId, openedAt: null }, data: { openedAt: new Date() } })
    .catch(() => null);

  await db.deliverabilityEvent
    .create({
      data: {
        type: "OPEN",
        inboxId: send.inboxId ?? null,
        sendingDomainId: send.inbox?.sendingDomainId ?? null,
        campaignId: send.campaignId,
        contactId: send.contactId,
        sendId: send.id,
      },
    })
    .catch(() => null);
  return true;
}

/** Record one CLICK for `sendId` to `url`. Returns false (no-op) if the send doesn't exist. */
export async function recordClickEvent(sendId: string, url: string): Promise<boolean> {
  const send = await loadSendContext(sendId).catch(() => null);
  if (!send) return false;

  const meta = url.slice(0, 300);
  await db.emailEvent.create({ data: { sendId, type: "CLICK", meta } }).catch(() => null);

  await db.coldSend
    .update({ where: { id: sendId }, data: { clickCount: { increment: 1 } } })
    .catch(() => null);
  await db.coldSend
    .updateMany({ where: { id: sendId, clickedAt: null }, data: { clickedAt: new Date() } })
    .catch(() => null);

  await db.deliverabilityEvent
    .create({
      data: {
        type: "CLICK",
        inboxId: send.inboxId ?? null,
        sendingDomainId: send.inbox?.sendingDomainId ?? null,
        campaignId: send.campaignId,
        contactId: send.contactId,
        sendId: send.id,
        meta,
      },
    })
    .catch(() => null);
  return true;
}

