1	import { NextResponse } from "next/server";
2	import { verifyClickToken } from "@/lib/coldemail/compliance";
3	import { recordClickEvent } from "@/lib/coldemail/track";
4	
5	export const dynamic = "force-dynamic";
6	export const runtime = "nodejs";
7	
8	/**
9	 * Click-tracking redirect. The destination URL is carried INSIDE the HMAC-signed
10	 * token (see clickTrackingToken), so an attacker cannot turn this into an open
11	 * redirect by swapping the target — an unsigned/tampered token 400s instead of
12	 * redirecting. verifyClickToken additionally requires an absolute http(s) URL.
13	 *
14	 * On a valid token it records a CLICK EmailEvent (best-effort) then 302s to the
15	 * real destination.
16	 */
17	export async function GET(_req: Request, { params }: { params: Promise<{ token: string }> }) {
18	  const { token } = await params;
19	  const claims = verifyClickToken(token);
20	  if (!claims) {
21	    return NextResponse.json({ error: "Invalid or expired link." }, { status: 400 });
22	  }
23	  // recordClickEvent never throws, but this route must redirect regardless.
24	  await recordClickEvent(claims.sendId, claims.url).catch(() => null);
25	  return NextResponse.redirect(claims.url, 302);
26	}
