// Cold Email Engine — LIVE DNS authentication recognition (pure core).
//
// PURE + unit-testable. This module holds NO I/O: it turns already-fetched TXT /
// CNAME answers into SPF / DKIM / DMARC verdicts. The live lookups live in the
// `verifyDomainDns` server action (lib/actions-coldemail.ts), which fetches the
// records through the zone's AUTHORITATIVE nameservers (never the local resolver
// — see lib/mail/deliverability.ts "THE RESOLVER TRAP") and hands the raw answers
// here. Keeping recognition pure means the SPF/DKIM/DMARC parsing is tested the
// same way it runs.

/** One record's verdict: did we recognise it, the raw value found, and why-not. */
export type DnsRecordCheck = {
  verified: boolean;
  /** The raw record we recognised at that host (null when nothing usable found). */
  record: string | null;
  /** Human-readable reason when not verified, or a lookup error. null when green. */
  error: string | null;
};

/** The full per-domain verdict returned by the verify action. */
export type DnsVerifyResult = {
  domain: string;
  dkimSelector: string;
  spf: DnsRecordCheck;
  dkim: DnsRecordCheck;
  dmarc: DnsRecordCheck;
  /** Present only for sending-domain checks that include a tracking CNAME. */
  tracking: (DnsRecordCheck & { host: string }) | null;
  /** ISO timestamp. */
  checkedAt: string;
  /** Set when authority for the zone could not be established at all. */
  lookupError: string | null;
};

/** Default DKIM selector when the operator does not specify one. */
export const DEFAULT_DKIM_SELECTOR = "default";

/** A TXT record's chunks are concatenated with NO separator (RFC 7208 §3.3). */
export function joinTxt(record: string[]): string {
  return record.join("").trim();
}

/** Trim + lower-case a selector; fall back to the default. Strips a stray dot. */
export function normalizeSelector(selector: string | null | undefined): string {
  const s = (selector ?? "").trim().toLowerCase().replace(/\.+$/, "");
  return s || DEFAULT_DKIM_SELECTOR;
}

// ---------------------------------------------------------------------------
// Record recognition (pure)
// ---------------------------------------------------------------------------

/** True for a TXT value that is an SPF record (starts `v=spf1`). */
export function isSpfRecord(txt: string): boolean {
  return /^v=spf1\b/i.test(txt.trim());
}

/** True for a TXT value that is a DMARC record (starts `v=DMARC1`). */
export function isDmarcRecord(txt: string): boolean {
  return /^v=DMARC1\b/i.test(txt.trim());
